param([Parameter(Mandatory)] [string]$PromptFile,[Parameter(Mandatory)] [string]$OutputFile,[string]$Model='gemma4:12b',[int]$TimeoutSec=600,[int]$PreDelaySec=0,[string]$QueueRoot='V:\AI\Miller\.miller\gemma-queue')
$ErrorActionPreference='Stop'; New-Item -ItemType Directory -Force -Path (Join-Path $QueueRoot 'pending') | Out-Null
$id="job-$(Get-Date -Format yyyyMMdd-HHmmss)-$([guid]::NewGuid().ToString('N').Substring(0,8))"; $job=[ordered]@{jobId=$id;promptPath=(Resolve-Path $PromptFile).Path;outputPath=$OutputFile;model=$Model;timeoutSec=$TimeoutSec;preDelaySec=$PreDelaySec;submittedTime=(Get-Date).ToUniversalTime().ToString('o')}; $tmp=Join-Path $QueueRoot "pending\.$id.tmp"; $job|ConvertTo-Json|Set-Content $tmp -Encoding UTF8; Move-Item $tmp (Join-Path $QueueRoot "pending\$id.json"); Write-Output "job ID: $id"; Write-Output "status path: $QueueRoot"; Write-Output "expected result path: $OutputFile"
